"""Generate host files and run Mihomo together with the stable selector."""
from datetime import datetime
import os
from pathlib import Path
import shlex
import signal
import socket
import subprocess
import sys
import time

from .provider import current_name
from .settings import Settings, repo_root


def render_proxy_env(settings: Settings) -> str:
    proxy = shlex.quote(settings.proxy)
    return "\n".join([
        "# Generated by codex-mihomo. Re-run install after changing ports.",
        f"export HTTP_PROXY={proxy}",
        'export HTTPS_PROXY="$HTTP_PROXY"',
        'export ALL_PROXY="$HTTP_PROXY"',
        'export http_proxy="$HTTP_PROXY"',
        'export https_proxy="$HTTP_PROXY"',
        'export all_proxy="$HTTP_PROXY"',
        "export NO_PROXY=127.0.0.1,localhost,::1",
        'export no_proxy="$NO_PROXY"',
        "export CODEX_BIN=" + shlex.quote(settings.codex_bin),
        "",
    ])


def render_codex_env(settings: Settings) -> str:
    lines = [
        "# Generated by codex-mihomo. Source this file from an interactive shell.",
        ". " + shlex.quote(str(settings.home / "proxy-env.sh")),
        "export PATH=" + shlex.quote(str(settings.home / "bin")) + ":$PATH",
    ]
    if settings.codex_home:
        lines.append("export CODEX_HOME=" + shlex.quote(settings.codex_home))
    lines.append("")
    return "\n".join(lines)


def render_wrapper() -> str:
    return """#!/bin/sh
set -eu
wrapper_dir=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
# shellcheck disable=SC1091
. "$wrapper_dir/../proxy-env.sh"
stripped=
IFS=:
for part in $PATH; do
    if [ "$part" != "$wrapper_dir" ]; then
        stripped=${stripped:+$stripped:}$part
    fi
done
unset IFS
PATH=$stripped
export PATH
codex_bin=${CODEX_BIN:-codex}
exec "$codex_bin" "$@"
"""


def render_run_mihomo(settings: Settings) -> str:
    binary = shlex.quote(str(settings.mihomo_bin))
    home = shlex.quote(str(settings.home))
    return f"""#!/bin/sh
set -eu
unset HTTP_PROXY HTTPS_PROXY ALL_PROXY http_proxy https_proxy all_proxy
exec {binary} -d {home}
"""


def _supervisor_quote(value: str) -> str:
    return str(value).replace("%", "%%").replace('"', "")


def render_supervisor(settings: Settings) -> str:
    root = repo_root()
    python = _supervisor_quote(sys.executable)
    config = _supervisor_quote(str(settings.config_path))
    user = f"user={settings.supervisor_user}\n" if settings.supervisor_user else ""
    common = f"""autostart=true
autorestart=true
startsecs=5
startretries=5
stopsignal=TERM
stopasgroup=true
killasgroup=true
{user}"""
    return f"""[program:{settings.service_name}]
command={settings.home / "run-mihomo.sh"}
directory={root}
{common}stdout_logfile={settings.home / "service.log"}
stderr_logfile={settings.home / "service.log"}
stdout_logfile_maxbytes=10MB
stderr_logfile_maxbytes=10MB

[program:{settings.service_name}-health]
command={python} -m codex_mihomo selector
directory={root}
environment=PYTHONPATH="{_supervisor_quote(str(root))}",CODEX_MIHOMO_CONFIG="{config}"
{common}stdout_logfile={settings.home / "selector.log"}
stderr_logfile={settings.home / "selector.log"}
stdout_logfile_maxbytes=5MB
stderr_logfile_maxbytes=5MB
"""


def render_systemd(settings: Settings, system: bool) -> str:
    wanted = "multi-user.target" if system else "default.target"
    root = repo_root()
    return f"""[Unit]
Description=Codex Mihomo proxy and stable selector
After=network-online.target

[Service]
Type=simple
Environment=PYTHONPATH={root}
Environment=CODEX_MIHOMO_CONFIG={settings.config_path}
WorkingDirectory={root}
ExecStart={sys.executable} -m codex_mihomo up
Restart=on-failure
RestartSec=3

[Install]
WantedBy={wanted}
"""


def ensure_include(text: str, path: str) -> str:
    lines = text.splitlines()
    include_at = None
    files_at = None
    for index, line in enumerate(lines):
        stripped = line.strip()
        if stripped == "[include]":
            include_at = index
            files_at = None
            continue
        if include_at is None:
            continue
        if stripped.startswith("[") and stripped.endswith("]"):
            break
        if stripped.startswith("files"):
            files_at = index
    if files_at is not None:
        if path in lines[files_at]:
            return text if text.endswith("\n") or not text else text + "\n"
        lines[files_at] = lines[files_at].rstrip() + " " + path
        return "\n".join(lines) + "\n"
    block = "files = " + path
    if include_at is not None:
        lines.insert(include_at + 1, block)
        return "\n".join(lines) + "\n"
    base = text
    if base and not base.endswith("\n"):
        base += "\n"
    if base and not base.endswith("\n\n"):
        base += "\n"
    return base + "[include]\n" + block + "\n"


def _write(path: Path, content: str, mode: int) -> None:
    path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    temporary = path.with_suffix(path.suffix + ".next")
    temporary.write_text(content, encoding="utf-8")
    os.chmod(temporary, mode)
    os.replace(temporary, path)
    os.chmod(path, mode)


def install(settings: Settings, supervisor_config: Path | None = None, systemd: str = "",
            shell_rc: Path | None = None, enable: bool = False) -> None:
    home = settings.home
    home.mkdir(mode=0o700, parents=True, exist_ok=True)
    os.chmod(home, 0o700)
    _write(home / "proxy-env.sh", render_proxy_env(settings), 0o644)
    _write(home / "codex-env.sh", render_codex_env(settings), 0o644)
    _write(home / "bin" / "codex", render_wrapper(), 0o755)
    _write(home / "run-mihomo.sh", render_run_mihomo(settings), 0o755)
    _write(home / "supervisor.ini", render_supervisor(settings), 0o644)
    _write(home / f"{settings.service_name}.service", render_systemd(settings, systemd == "system"), 0o644)
    print("Prepared " + str(home))
    print("Foreground, both processes: python3 -m codex_mihomo up")

    if supervisor_config:
        _install_supervisor(settings, supervisor_config)
    if systemd:
        _install_systemd(settings, systemd, enable)
    if shell_rc:
        _install_shell(settings, shell_rc)


def _install_supervisor(settings: Settings, supervisor_config: Path) -> None:
    original = supervisor_config.read_text(encoding="utf-8") if supervisor_config.exists() else ""
    updated = ensure_include(original, str(settings.home / "supervisor.ini"))
    normalized = original if original.endswith("\n") or not original else original + "\n"
    if updated != normalized:
        if supervisor_config.exists():
            stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
            backup = supervisor_config.with_name(supervisor_config.name + f".backup-{stamp}")
            backup.write_bytes(supervisor_config.read_bytes())
        supervisor_config.parent.mkdir(parents=True, exist_ok=True)
        supervisor_config.write_text(updated, encoding="utf-8")
    subprocess.run(["supervisorctl", "-c", str(supervisor_config), "reread"], check=True)
    subprocess.run(["supervisorctl", "-c", str(supervisor_config), "update"], check=True)
    subprocess.run(["supervisorctl", "-c", str(supervisor_config), "status",
                    settings.service_name, settings.service_name + "-health"], check=False)


def _install_systemd(settings: Settings, kind: str, enable: bool) -> None:
    unit = settings.home / f"{settings.service_name}.service"
    if kind == "user":
        destination = Path.home() / ".config" / "systemd" / "user" / unit.name
        command = ["systemctl", "--user"]
    else:
        destination = Path("/etc/systemd/system") / unit.name
        command = ["systemctl"]
    if not os.access(destination.parent, os.W_OK):
        print("Systemd unit is at " + str(unit) + "; copy it to " + str(destination))
        return
    destination.parent.mkdir(parents=True, exist_ok=True)
    destination.write_text(unit.read_text(encoding="utf-8"), encoding="utf-8")
    print("Systemd unit written to " + str(destination))
    if enable:
        subprocess.run([*command, "daemon-reload"], check=True)
        subprocess.run([*command, "enable", "--now", settings.service_name], check=True)


def _install_shell(settings: Settings, shell_rc: Path) -> None:
    marker = "# [codex-mihomo]"
    hook = f'[ -r {shlex.quote(str(settings.home / "codex-env.sh"))} ] && . {shlex.quote(str(settings.home / "codex-env.sh"))} {marker}\n'
    existing = shell_rc.read_text(encoding="utf-8") if shell_rc.exists() else ""
    if marker in existing:
        print("Shell hook already present in " + str(shell_rc))
        return
    if shell_rc.exists():
        stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
        backup = shell_rc.with_name(shell_rc.name + f".backup-{stamp}")
        backup.write_text(existing, encoding="utf-8")
    shell_rc.parent.mkdir(parents=True, exist_ok=True)
    shell_rc.write_text(existing + ("" if existing.endswith("\n") or not existing else "\n") + hook, encoding="utf-8")
    print("Shell hook appended to " + str(shell_rc))


def up(settings: Settings) -> int:
    if not settings.mihomo_bin.is_file() or not os.access(settings.mihomo_bin, os.X_OK):
        raise SystemExit("Mihomo binary is missing or not executable: " + str(settings.mihomo_bin))
    if not (settings.home / "config.yaml").is_file():
        raise SystemExit("No config.yaml in the runtime home. Register a provider and run `provider use` first.")
    proxy_env = os.environ.copy()
    for key in ("HTTP_PROXY", "HTTPS_PROXY", "ALL_PROXY", "http_proxy", "https_proxy", "all_proxy"):
        proxy_env.pop(key, None)
    selector_env = os.environ.copy()
    selector_env["PYTHONPATH"] = str(repo_root()) + os.pathsep + selector_env.get("PYTHONPATH", "")
    selector_env["CODEX_MIHOMO_CONFIG"] = str(settings.config_path)
    mihomo = subprocess.Popen([str(settings.mihomo_bin), "-d", str(settings.home)], env=proxy_env)
    selector = subprocess.Popen(
        [sys.executable, "-m", "codex_mihomo", "selector"],
        cwd=str(repo_root()), env=selector_env,
    )
    children = (mihomo, selector)

    def stop(*_args):
        for process in children:
            if process.poll() is None:
                process.terminate()

    signal.signal(signal.SIGTERM, stop)
    signal.signal(signal.SIGINT, stop)
    while mihomo.poll() is None and selector.poll() is None:
        time.sleep(0.5)
    stop()
    codes = []
    for process in children:
        try:
            codes.append(process.wait(timeout=10))
        except subprocess.TimeoutExpired:
            process.kill()
            codes.append(process.wait())
    return next((code for code in codes if code), 0)


def _listening(host: str, port: int) -> bool:
    try:
        with socket.create_connection((host, port), timeout=0.3):
            return True
    except OSError:
        return False


def doctor(settings: Settings) -> int:
    print("config:", settings.config_path, "present" if settings.config_path.is_file() else "missing; using defaults")
    print("home:", settings.home)
    print("mihomo:", settings.mihomo_bin, "ok" if settings.mihomo_bin.is_file() else "missing")
    print("active-config:", "present" if (settings.home / "config.yaml").is_file() else "missing")
    try:
        print("active-provider:", current_name(settings))
    except (OSError, ValueError):
        print("active-provider: unreadable")
    failed = False
    for label, port in (("mixed", settings.mixed_port), ("controller", settings.controller_port)):
        listening = _listening(settings.bind_address, port)
        print(f"{label}: {settings.bind_address}:{port}", "listening" if listening else "down")
        failed = failed or not listening
    state = settings.home / "selector-state.json"
    if state.is_file() and time.time() - state.stat().st_mtime < max(30, settings.health_interval * 3):
        print("selector: recent state update")
    else:
        print("selector: no recent state update")
        failed = True
    if not failed:
        from .provider import probe
        print("health-check:", "expected" if probe(settings, settings.mixed_port) else "unexpected")
    return 1 if failed else 0
